import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const charge = async (h: any, id: string, outcome: 'ok' | 'failed') => {
  const e = (await h.pendingEffects()).find((x: any) => x.from === id && x.kind === 'payment.charge');
  assert.ok(e);
  await h.completeEffect(e.id, outcome);
};

test('happy path, ship', async () => {
  const h: any = await createHost();
  assert.equal(await h.order('a'), null);
  assert.equal((await h.addItem('a')).ok, false);
  assert.equal(await h.order('a'), null);
  assert.deepEqual(await h.create('a'), { ok: true });
  assert.equal((await h.create('a')).ok, false);
  assert.equal((await h.place('a')).ok, false);
  for (let i = 0; i < 3; i++) assert.equal((await h.addItem('a')).ok, true);
  assert.equal((await h.addItem('a')).ok, false);
  assert.equal((await h.removeItem('a')).ok, true);
  assert.equal((await h.place('a')).ok, true);
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal((await h.place('a')).ok, false);
  const pend = await h.pendingEffects();
  assert.equal(pend.length, 1);
  assert.deepEqual(pend[0].data, { amount: 2 });
  assert.equal((await h.ship('a')).ok, false);
  await charge(h, 'a', 'ok');
  assert.deepEqual(await h.order('a'), { status: 'paid', items: 2, charges: 1, refunds: 0 });
  assert.equal((await h.pendingEffects()).length, 0);
  assert.equal((await h.ship('a')).ok, true);
  assert.equal((await h.cancel('a')).ok, false);
  assert.deepEqual(await h.order('a'), { status: 'shipped', items: 2, charges: 1, refunds: 0 });
  await h.__dispose();
});

test('cancel paid refunds; failed charge', async () => {
  const h: any = await createHost();
  await h.create('a'); await h.addItem('a'); await h.place('a');
  await charge(h, 'a', 'ok');
  assert.equal((await h.cancel('a')).ok, true);
  assert.deepEqual(await h.order('a'), { status: 'cancelled', items: 1, charges: 1, refunds: 1 });
  assert.equal((await h.cancel('a')).ok, false);
  await h.create('b'); await h.addItem('b'); await h.place('b');
  await charge(h, 'b', 'failed');
  assert.deepEqual(await h.order('b'), { status: 'failed', items: 1, charges: 1, refunds: 0 });
  assert.equal((await h.cancel('b')).ok, false);
  await h.create('c');
  assert.equal((await h.cancel('c')).ok, true);
  assert.deepEqual(await h.order('c'), { status: 'cancelled', items: 0, charges: 0, refunds: 0 });
  const [r] = await h.pendingEffects();
  assert.equal(r.kind, 'payment.refund');
  await h.completeEffect(r.id, 'failed');
  assert.equal((await h.pendingEffects()).length, 0);
  assert.deepEqual(await h.order('a'), { status: 'cancelled', items: 1, charges: 1, refunds: 1 });
  await h.__dispose();
});

prompt:
The brief has changed. Here is the change, in addition to everything the brief said before:

# Change 2: cancel while the payment is in progress

A placed order can now be cancelled while its charge is in progress. The provider still answers, and the answer decides whether money must be returned.

- `cancel(order)`: a placed order becomes **cancelling**. No refund is requested yet.
- When the charge of a cancelling order completes `ok`, it went through after all: the order becomes **cancelled** and one refund is requested.
- When it completes `failed`, nothing was taken: the order becomes **cancelled**, and no refund is requested.
- A cancelling order accepts no other command.

`status` in the view can now also be `"cancelling"`. Everything else is as before, including cancelling a draft or a paid order.

The host interface is now as follows, and `host.ts` has been updated to match.

```ts
// T1 after change 2, order lifecycle with payment retry and cancelling: the host interface every arm implements (PT13).

/** The outcome of a command: it took effect, or it was refused and changed nothing. */
export type Outcome = { ok: true } | { ok: false; reason: string };

/** An effect the system asked the outside world to carry out, not yet completed. */
export interface Effect {
  id: string;
  /** The order that requested it. */
  from: string;
  kind: string;
  data: Record<string, unknown>;
}

/** The effect port: what the payment provider is asked to do, and its answers. */
export interface Effects {
  /** Every effect requested and not yet completed, in no promised order. */
  pendingEffects(): Promise<Effect[]>;
  /** The provider's answer to a pending effect: it went through (ok) or it did not (failed). */
  completeEffect(id: string, outcome: 'ok' | 'failed'): Promise<void>;
}

export interface OrderView {
  status: 'draft' | 'placed' | 'paid' | 'shipped' | 'cancelling' | 'cancelled' | 'declined' | 'failed';
  items: number;
  charges: number;
  refunds: number;
}

export interface Host extends Effects {
  create(order: string): Promise<Outcome>;
  addItem(order: string): Promise<Outcome>;
  removeItem(order: string): Promise<Outcome>;
  place(order: string): Promise<Outcome>;
  ship(order: string): Promise<Outcome>;
  cancel(order: string): Promise<Outcome>;
  retryPayment(order: string): Promise<Outcome>;
  /** The order, or null when no order has that id. */
  order(order: string): Promise<OrderView | null>;
}

/** The module's default export: a factory of a fresh system, with no orders. */
export type CreateHost = () => Promise<Host>;
```

