import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const charge = async (h: any, id: string, outcome: 'ok' | 'failed') => {
  const e = (await h.pendingEffects()).find((x: any) => x.from === id && x.kind === 'payment.charge');
  assert.ok(e);
  await h.completeEffect(e.id, outcome);
};

test('happy path, ship', async () => {
  const h: any = await createHost();
  assert.equal(await h.order('a'), null);
  assert.equal((await h.addItem('a')).ok, false);
  assert.equal(await h.order('a'), null);
  assert.deepEqual(await h.create('a'), { ok: true });
  assert.equal((await h.create('a')).ok, false);
  assert.equal((await h.place('a')).ok, false);
  for (let i = 0; i < 3; i++) assert.equal((await h.addItem('a')).ok, true);
  assert.equal((await h.addItem('a')).ok, false);
  assert.equal((await h.removeItem('a')).ok, true);
  assert.equal((await h.place('a')).ok, true);
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal((await h.place('a')).ok, false);
  const pend = await h.pendingEffects();
  assert.equal(pend.length, 1);
  assert.deepEqual(pend[0].data, { amount: 2 });
  assert.equal((await h.ship('a')).ok, false);
  await charge(h, 'a', 'ok');
  assert.deepEqual(await h.order('a'), { status: 'paid', items: 2, charges: 1, refunds: 0 });
  assert.equal((await h.pendingEffects()).length, 0);
  assert.equal((await h.ship('a')).ok, true);
  assert.equal((await h.cancel('a')).ok, false);
  assert.deepEqual(await h.order('a'), { status: 'shipped', items: 2, charges: 1, refunds: 0 });
  await h.__dispose();
});

test('cancel paid refunds; failed charge', async () => {
  const h: any = await createHost();
  await h.create('a'); await h.addItem('a'); await h.place('a');
  await charge(h, 'a', 'ok');
  assert.equal((await h.cancel('a')).ok, true);
  assert.deepEqual(await h.order('a'), { status: 'cancelled', items: 1, charges: 1, refunds: 1 });
  assert.equal((await h.cancel('a')).ok, false);
  await h.create('b'); await h.addItem('b'); await h.place('b');
  assert.equal((await h.retryPayment('b')).ok, false);
  await charge(h, 'b', 'failed');
  assert.deepEqual(await h.order('b'), { status: 'declined', items: 1, charges: 1, refunds: 0 });
  for (const m of ['cancel', 'addItem', 'removeItem', 'place', 'ship']) assert.equal((await h[m]('b')).ok, false);
  assert.equal((await h.retryPayment('b')).ok, true);
  assert.equal((await h.retryPayment('b')).ok, false);
  assert.deepEqual(await h.order('b'), { status: 'placed', items: 1, charges: 2, refunds: 0 });
  await charge(h, 'b', 'failed');
  assert.deepEqual(await h.order('b'), { status: 'failed', items: 1, charges: 2, refunds: 0 });
  assert.equal((await h.cancel('b')).ok, false);
  assert.equal((await h.retryPayment('b')).ok, false);
  await h.create('d'); await h.addItem('d'); await h.place('d');
  await charge(h, 'd', 'failed');
  await h.retryPayment('d');
  await charge(h, 'd', 'ok');
  assert.deepEqual(await h.order('d'), { status: 'paid', items: 1, charges: 2, refunds: 0 });
  assert.equal((await h.cancel('d')).ok, true);
  assert.deepEqual(await h.order('d'), { status: 'cancelled', items: 1, charges: 2, refunds: 1 });
  for (const e of await h.pendingEffects()) if (e.from === 'd') await h.completeEffect(e.id, 'ok');
  await h.create('c');
  assert.equal((await h.cancel('c')).ok, true);
  assert.deepEqual(await h.order('c'), { status: 'cancelled', items: 0, charges: 0, refunds: 0 });
  const [r] = await h.pendingEffects();
  assert.equal(r.kind, 'payment.refund');
  await h.completeEffect(r.id, 'failed');
  assert.equal((await h.pendingEffects()).length, 0);
  assert.deepEqual(await h.order('a'), { status: 'cancelled', items: 1, charges: 1, refunds: 1 });
  await h.__dispose();
});

