// T1, order lifecycle: one Order machine per order id. The status members are spelled as the host
// interface reports them; `fresh` is the instance before `create` takes effect, never visible.
module shop

enum Status { fresh, draft, placed, paid, shipped, cancelling, cancelled, declined, failed }

machine Order {
  state {
    status  : Status = fresh
    items   : 0..3   = 0
    charges : 0..2   = 0
    refunds : 0..1   = 0
    refundAnswered : bool = false
    held    : bool   = false
  }
  terminal status in { shipped, cancelled, failed }

  action Create()
  action AddItem()
  action RemoveItem()
  action Place()
  action Ship()
  action Cancel()
  action PaymentOk()
  action PaymentFailed()
  action RefundAnswered()
  action RetryPayment()
  action Hold()
  action Release()

  on Create {
    require status == fresh else reject "exists"
    status' = draft
  }
  on AddItem {
    require status == draft else reject "not-draft"
    require items < 3 else reject "order-full"
    items' = items + 1
  }
  on RemoveItem {
    require status == draft else reject "not-draft"
    require items > 0 else reject "order-empty"
    items' = items - 1
  }
  on Place {
    require status == draft else reject "not-draft"
    require items > 0 else reject "order-empty"
    require charges == 0 else reject "already-charged"
    status' = placed
    charges' = charges + 1
    emit charge(items)
  }
  // A charge that went through on a cancelling order is returned at once.
  on PaymentOk {
    require status in { placed, cancelling } else reject "not-placed"
    require refunds == 0 else reject "already-refunded"
    if status == cancelling {
      status' = cancelled
      refunds' = refunds + 1
      emit refund(items)
    } else {
      status' = paid
    }
  }
  on PaymentFailed {
    require status in { placed, cancelling } else reject "not-placed"
    if status == cancelling {
      status' = cancelled
    } else {
      if charges == 1 { status' = declined } else { status' = failed }
    }
  }
  on RetryPayment {
    require status == declined else reject "not-declined"
    require charges == 1 else reject "retried"
    status' = placed
    charges' = charges + 1
    emit charge(items)
  }
  // The refund needs no answer; one that comes is recorded and changes nothing the host shows.
  on RefundAnswered {
    require refunds == 1 && !refundAnswered else reject "no-refund-pending"
    refundAnswered' = true
  }
  on Ship {
    require status == paid else reject "not-paid"
    require !held else reject "held"
    status' = shipped
  }
  on Hold {
    require status == paid else reject "not-paid"
    require !held else reject "held"
    held' = true
  }
  on Release {
    require held else reject "not-held"
    held' = false
  }
  on Cancel {
    require status in { draft, placed, paid } else reject "not-cancellable"
    require refunds == 0 else reject "already-refunded"
    if status == paid {
      refunds' = refunds + 1
      emit refund(items)
      status' = cancelled
      held' = false
    } else {
      if status == placed { status' = cancelling } else { status' = cancelled }
    }
  }

  invariant paid-was-charged: status in { paid, shipped } implies charges >= 1
  invariant refund-after-charge: refunds <= charges
  invariant draft-not-charged: status in { fresh, draft } implies charges == 0
  invariant cancelling-not-refunded: status == cancelling implies (charges >= 1 && refunds == 0)
  invariant declined-after-first: status == declined implies charges == 1
  invariant failed-after-second: status == failed implies charges == 2
  path property charge-at-most-twice: count("payment.charge") <= 2
  path property refund-at-most-once: count("payment.refund") <= 1
  path property refund-after-charge-path: before("payment.charge", "payment.refund")

  effect charge(amount: int) {
    kind "payment.charge"
    labels { egress:external }
    class irreversible
    ok -> PaymentOk()
    failed -> PaymentFailed()
  }
  effect refund(amount: int) {
    kind "payment.refund"
    labels { egress:external }
    class irreversible
    ok -> RefundAnswered()
    failed -> RefundAnswered()
  }
}

